9	/**
10	 * Runs after {@link ValidateOwnerFields} in {@code POST /api/owners}, reading the
11	 * already-normalized body as a variable. Rejects the request when its telephone is already
12	 * used by another owner (comparing canonical E.164 telephones), throwing
13	 * {@link DuplicateOwnerTelephoneException} for a 409 before any entity is built or persisted.
14	 */
15	public class EnsureUniqueOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateOwnerTelephoneException {
19	
20	        String telephone = request.getTelephone(); // already normalized to E.164 upstream
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (OwnerTelephone.toE164(existing.getTelephone()).map(telephone::equals).orElse(false)) {
23	                throw new DuplicateOwnerTelephoneException(telephone);
24	            }
25	        }
26	    }
27	}
