9	/**
10	 * Runs in {@code POST /api/owners} after the telephone-uniqueness check, reading the
11	 * already-validated body as a variable. Rejects the request when another owner already
12	 * shares its lastName and address (compared case-insensitively with collapsed whitespace),
13	 * throwing {@link DuplicateOwnerHouseholdException} for a 409 before any entity is built or
14	 * persisted. A request that opts in with {@code sharesHousehold=true} is allowed through.
15	 */
16	public class EnsureUniqueOwnerHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateOwnerHouseholdException {
20	
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return; // caller acknowledges the shared household
23	        }
24	
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (Household.same(request.getLastName(), request.getAddress(),
27	                    existing.getLastName(), existing.getAddress())) {
28	                throw new DuplicateOwnerHouseholdException(request.getLastName());
29	            }
30	        }
31	    }
32	}
