1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Runs in {@code POST /api/owners} after the owner entity is built, only when the request
10	 * opted in with {@code sharesHousehold=true}. Assigns the built owner the stable
11	 * {@link Household#id(String, String) household id} for its lastName and address, and backfills
12	 * that same id onto any existing owner in the household so every member shares it. Runs within
13	 * the create transaction, before the owner is saved.
14	 */
15	public class AssignOwnerHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
18	
19	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
20	            return; // only owners joining an existing household get a shared id
21	        }
22	
23	        String householdId = Household.id(owner.getLastName(), owner.getAddress());
24	        owner.setHouseholdId(householdId);
25	
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (Household.same(owner.getLastName(), owner.getAddress(),
28	                    existing.getLastName(), existing.getAddress())
29	                    && !householdId.equals(existing.getHouseholdId())) {
30	                existing.setHouseholdId(householdId);
31	                ownerRepository.save(existing);
32	            }
33	        }
34	    }
35	}
