1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Address normalization shared by the owner pipelines and the household identity: produces
8	 * an address's canonical form so it is stored, returned and compared in one consistent
9	 * representation. Normalizing means trimming and collapsing whitespace, upper-casing, and
10	 * expanding common street-type abbreviations to their full word.
11	 */
12	public final class OwnerAddress {
13	
14	    /** Whole-token abbreviations expanded to their full word (compared upper-cased). */
15	    private static final Map<String, String> ABBREVIATIONS = Map.of(
16	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
17	
18	    private OwnerAddress() {
19	    }
20	
21	    /**
22	     * The canonical form of {@code address}: trimmed, internal whitespace collapsed to single
23	     * spaces, upper-cased, with each abbreviation token expanded. A {@code null} address, or one
24	     * that is blank once trimmed, yields the empty string.
25	     */
26	    public static String normalize(String address) {
27	        if (address == null) {
28	            return "";
29	        }
30	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder sb = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                sb.append(' ');
39	            }
40	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
41	        }
42	        return sb.toString();
43	    }
44	}
